def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n < 3:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    total_cC = total_cD = total_dC = total_dD = 0
    recent_cC = recent_cD = recent_dC = recent_dD = 0

    rec_start = 1
    if n > 10:
        rec_start = n - 10

    for i in range(1, n):
        prev_me = me[i - 1]
        cur_opp = opp[i]
        in_recent = i >= rec_start
        if prev_me == 'C':
            if cur_opp == 'C':
                total_cC += 1
                if in_recent:
                    recent_cC += 1
            else:
                total_cD += 1
                if in_recent:
                    recent_cD += 1
        else:
            if cur_opp == 'C':
                total_dC += 1
                if in_recent:
                    recent_dC += 1
            else:
                total_dD += 1
                if in_recent:
                    recent_dD += 1

    rec_c = recent_cC + recent_cD
    rec_d = recent_dC + recent_dD
    tot_c = total_cC + total_cD
    tot_d = total_dC + total_dD

    recent_len = n if n < 10 else 10
    recent_opp_c = 0
    for a in opp[-recent_len:]:
        if a == 'C':
            recent_opp_c += 1
    recent_opp_d = recent_len - recent_opp_c

    if rec_c >= 3:
        pC = float(recent_cC) / float(rec_c)
    elif tot_c >= 3:
        pC = float(total_cC) / float(tot_c)
    else:
        pC = float(recent_opp_c) / float(recent_len) if recent_len > 0 else 1.0

    if rec_d >= 3:
        pD = float(recent_dC) / float(rec_d)
    elif tot_d >= 3:
        pD = float(total_dC) / float(tot_d)
    else:
        pD = pC

    reward = pC - pD
    last_me, last_opp = history[-1]

    cons_opp_d = 0
    for a in reversed(opp):
        if a == 'D':
            cons_opp_d += 1
        else:
            break

    cons_me_d = 0
    for a in reversed(me):
        if a == 'D':
            cons_me_d += 1
        else:
            break

    if last_opp == 'C':
        if reward > 0.25 and pD < 0.45 and pC > 0.55:
            return 'C'
        return 'D'

    if reward > 0.20 and pD < 0.40 and pC > 0.45:
        return 'C'

    if n < 95 and cons_me_d >= 4 and cons_opp_d >= 4:
        if pC > 0.50 and pD < 0.55 and rng.random() < 0.20:
            return 'C'
        if rng.random() < 0.05:
            return 'C'

    if (
        cons_opp_d <= 2
        and reward > 0.50
        and pC > 0.75
        and pD < 0.55
        and rng.random() < 0.12
    ):
        return 'C'

    return 'D'
